func withRetry<T: Sendable>(
    maxAttempts: Int = 4,
    base: Duration = .milliseconds(300),
    cap: Duration = .seconds(10),
    isRetryable: (Error) -> Bool = { ($0 as? URLError)?.code == .timedOut || ($0 as? URLError)?.code == .networkConnectionLost },
    _ operation: () async throws -> T
) async throws -> T {
    var attempt = 0
    while true {
        do { return try await operation() }
        catch {
            attempt += 1
            if error is CancellationError || attempt >= maxAttempts || !isRetryable(error) { throw error }
            let exp = min(cap, base * (1 << attempt))
            let ms = Double(exp.components.seconds) * 1000 + Double(exp.components.attoseconds) / 1e15
            try await Task.sleep(for: .milliseconds(Int.random(in: 0...Int(ms))))   // full jitter
        }
    }
}
